class Solution {
    public int stoneGameVI(int[] aliceValues, int[] bobValues) {
        int n = aliceValues.length;
        Integer[] order = new Integer[n];
        for (int i = 0; i < n; i++) {
            order[i] = i;
        }
        // Sort indices by aliceValues[i] + bobValues[i] in descending order
        java.util.Arrays.sort(order, (a, b) -> {
            int sumA = aliceValues[a] + bobValues[a];
            int sumB = aliceValues[b] + bobValues[b];
            return Integer.compare(sumB, sumA); // descending
        });

        long aliceScore = 0L;
        long bobScore = 0L;
        for (int turn = 0; turn < n; turn++) {
            int idx = order[turn];
            if (turn % 2 == 0) {
                aliceScore += aliceValues[idx];
            } else {
                bobScore += bobValues[idx];
            }
        }

        if (aliceScore > bobScore) return 1;
        if (aliceScore < bobScore) return -1;
        return 0;
    }
}

