        order = [(aliceValues[i] + bobValues[i], i) for i in range(n)]
        order.sort(key=lambda x: x[0], reverse=True)

        aliceScore = 0
        bobScore = 0
        for turn, (_, idx) in enumerate(order):
            if turn % 2 == 0:
                aliceScore += aliceValues[idx]
            else:
                bobScore += bobValues[idx]

        if aliceScore > bobScore:
            return 1
        if aliceScore < bobScore:
            return -1
