/**
 * @param {number[]} aliceValues
 * @param {number[]} bobValues
 * @return {number}
 */
var stoneGameVI = function(aliceValues, bobValues) {
    const n = aliceValues.length;
    const order = new Array(n);
    for (let i = 0; i < n; ++i) {
        order[i] = { sum: aliceValues[i] + bobValues[i], idx: i };
    }
    order.sort((a, b) => b.sum - a.sum); // descending by sum

    let aliceScore = 0;
    let bobScore = 0;
    for (let turn = 0; turn < n; ++turn) {
        const idx = order[turn].idx;
        if (turn % 2 === 0) {
            aliceScore += aliceValues[idx];
        } else {
            bobScore += bobValues[idx];
        }
    }
    if (aliceScore > bobScore) return 1;
    if (aliceScore < bobScore) return -1;
    return 0;
};
